<?php

declare(strict_types=1);require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/google_drive.php';require_admin();$error='';try{if(isset($_GET['code'])){if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_GET['state']??'')))throw new RuntimeException('OAuth state ไม่ถูกต้อง');drive_save_token(drive_exchange_code((string)$_GET['code']));audit('connect_drive');flash('success','เชื่อมต่อ Google Drive สำเร็จ');redirect('admin/google-drive.php');}if(($_GET['action']??'')==='connect'){if(GOOGLE_CLIENT_ID===''||GOOGLE_CLIENT_SECRET==='')throw new RuntimeException('กรุณาตั้งค่า Client ID และ Client Secret');header('Location: '.drive_authorize_url());exit;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();db()->exec('DELETE FROM drive_connections WHERE id=1');audit('disconnect_drive');flash('success','ยกเลิกการเชื่อมต่อแล้ว');redirect('admin/google-drive.php');}}catch(Throwable $e){$error=$e->getMessage();}$connection=drive_connection();page_header('Google Drive',true);require __DIR__.'/_nav.php';?><h1>เชื่อมต่อ Google Drive</h1><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><div class="form-card"><p><strong>Redirect URI:</strong> <?=e(GOOGLE_REDIRECT_URI)?></p><?php if($connection):?><div class="notice success">เชื่อมต่อแล้ว Token หมดอายุ <?=e($connection['expires_at'])?></div><div class="actions"><a class="btn" href="?action=connect">เชื่อมต่อใหม่</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="btn danger">ยกเลิกการเชื่อมต่อ</button></form></div><?php else:?><a class="btn" href="?action=connect">เชื่อมต่อบัญชี Google</a><?php endif?></div><?php page_footer();?>
